L1: #!/usr/bin/env node
L2: // Writes the bar-widget settings block of manifest.json from Schema.js, like this: `barWidget.defaults` (every default) and `barWidget.schema` (key, type,
L3: // label, options, range, default, description). Run it after you change Schema.js:
L4: //   node tools/gen-manifest.js          writes manifest.json
L5: //   node tools/gen-manifest.js --check  fails if manifest.json is out of date (used by tests/test_manifest.js)
L6: "use strict";
L7: const fs = require("fs");
L8: const path = require("path");
L9: const root = path.resolve(__dirname, "..");
L10: const read = (f) => fs.readFileSync(path.join(root, "qml", "js", f), "utf8").replace(/^\s*\.pragma library.*$/m, "");
L11: const S = new Function(read("Schema.js") + "\n;return { groups: groups, defaults: defaults };")();
L12: 
L13: function entry(it, key, def) {
L14:     const e = { key, type: "string", label: it.label };
L15:     if (it.kind === "enum" && Array.isArray(it.options) && it.options.length) { e.type = "enum"; e.options = it.options.map(String); }
L16:     else if (it.kind === "int") { e.type = "integer"; e.min = it.min; e.max = it.max; e.step = it.step; }
L17:     else if (it.kind === "bool") e.type = "boolean";
L18:     e.defaultValue = def;
L19:     if (it.hint) e.description = it.hint;
L20:     return e;
L21: }
L22: 
L23: function build() {
L24:     const schema = [], seen = new Set();
L25:     for (const g of S.groups) for (const it of g.items) {
L26:         if (it.kind === "palette") {
L27:             for (const t of it.targets) if (!seen.has(t.key)) { seen.add(t.key); schema.push(entry({ label: t.label, hint: it.hint, kind: "string" }, t.key, S.defaults[t.key])); }
L28:         } else if (it.key && !seen.has(it.key)) {
L29:             seen.add(it.key);
L30:             schema.push(entry(it, it.key, S.defaults[it.key]));
L31:         }
L32:     }
L33:     const defaults = {};
L34:     for (const e of schema) defaults[e.key] = e.defaultValue;
L35:     return { defaults, schema };
L36: }

