L2: "use strict";
L3: const { spawnSync } = require("child_process");
L4: const fs = require("fs"), os = require("os"), path = require("path");
L5: let fails = 0;
L6: const ok = (c, m) => { if (c) console.log("ok   " + m); else { fails++; console.log("FAIL " + m); } };
L7: const tools = path.join(__dirname, "..", "tools");
L8: const empty = fs.mkdtempSync(path.join(os.tmpdir(), "pawmpt-nobin-"));
L9: const py = ["/usr/bin/python3", "/bin/python3"].find((p) => fs.existsSync(p)) || "python3";
L10: const run = (bridge, input) => spawnSync(py, [path.join(tools, bridge)], { input, encoding: "utf8", timeout: 20000, env: { PATH: empty, HOME: empty } });
L11: for (const [bridge, name] of [["opencode_bridge.py", "opencode"], ["claude_bridge.py", "Claude Code"], ["codex_bridge.py", "Codex"]]) {
L12:     let r = run(bridge, JSON.stringify({ pawmpt: "request", prompt: "hi" }) + "\n");
L13:     const lines = String(r.stdout).trim().split("\n").filter(Boolean).map((l) => { try { return JSON.parse(l); } catch (e) { return null; } });
L14:     ok(r.status === 127, bridge + ": a missing " + name + " is exit 127 (" + r.status + ")");
L15:     ok(lines.length > 0 && lines.every((e) => e && e.pawmpt === "text"), bridge + ": everything it prints is a Pawmpt event");
L16:     ok(lines.some((e) => e && e.text.includes("not installed")), bridge + ": and it says " + name + " is not installed");
L17:     ok(!String(r.stderr).includes("Traceback"), bridge + ": no traceback");
L18:     r = run(bridge, "not json\n");
L19:     ok(r.status === 2 && !String(r.stderr).includes("Traceback"), bridge + ": a request it can't read is exit 2, without a traceback");
L20: }
L21: // opencode's rules in Service.qml: a search reads every file under its folder, hidden ones included,
L22: // and opencode checks it apart from reading, so it always goes to the bridge, which checks the folder
L23: const service = fs.readFileSync(path.join(__dirname, "..", "qml", "Service.qml"), "utf8");
L24: const rules = service.slice(service.indexOf("readonly property var opencodeRules"), service.indexOf("readonly property string opencodeConfig"));
L25: ok((rules.match(/grep: "ask"/g) || []).length === 2 && !/grep: "allow"/.test(rules), "opencode: a search asks the bridge, with Let it act off and on");
L26: ok((rules.match(/lsp: "ask"/g) || []).length === 2 && !/lsp: "allow"/.test(rules), "opencode: so does the language server");
L27: // file rules are matched against the path from the project's top folder, so ".ssh/x" must be caught too
L28: const secretList = JSON.parse(service.match(/readonly property var secretFiles: (\[[^\]]*\])/)[1].replace(/\s+/g, " "));
L29: const relative = secretList.filter((f) => f.startsWith("*/")).map((f) => f.slice(2));
L30: ok(relative.length > 5 && /if \(f\.startsWith\("\*\/"\)\) out\.push\(f\.slice\(2\)\)/.test(service) && /for \(const f of secretRules\) read\[f\] = "deny"/.test(service),
L31:     "opencode: key files are kept from reading also by their path from the project's top folder (" + relative.slice(0, 2).join(", ") + ", ...)");
L32: ok(/for \(const f of secretRules\) edit\[f\] = "deny"/.test(service) && (rules.match(/edit: edit/g) || []).length === 2,
L33:     "opencode: and from editing, with Let it act off and on");
